/**
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "site-settings".
 */
export interface SiteSetting {
  id: number;
  businessName: string;
  tagline?: string | null;
  /**
   * Used for Google and link previews.
   */
  description?: string | null;
  /**
   * Registered business or company name. Leave empty until confirmed.
   */
  registeredName?: string | null;
  /**
   * Leave empty until confirmed.
   */
  ssmNumber?: string | null;
  /**
   * As shown, e.g. +60 12-421 1205
   */
  phone: string;
  /**
   * Digits only with country code, e.g. 60124211205
   */
  whatsapp: string;
  email: string;
  /**
   * Where new order and enquiry alerts go. Defaults to the email above.
   */
  notificationEmail?: string | null;
  socials?:
    | {
        platform: 'instagram' | 'tiktok' | 'facebook' | 'xiaohongshu' | 'youtube';
        handle: string;
        url: string;
        id?: string | null;
      }[]
    | null;
  address: {
    line1: string;
    line2?: string | null;
    postcode: string;
    city: string;
    state: string;
    country?: string | null;
  };
  /**
   * The "Share" link from Google Maps.
   */
  mapsUrl?: string | null;
  /**
   * Leave empty until confirmed; the site then says appointments are recommended.
   */
  hours?:
    | {
        /**
         * e.g. Tuesday to Saturday
         */
        days: string;
        /**
         * e.g. 11:00am – 7:00pm, or Closed
         */
        time: string;
        id?: string | null;
      }[]
    | null;
  visitNote?: string | null;
  announcement?: {
    enabled?: boolean | null;
    text?: string | null;
    /**
     * Optional, e.g. /shop
     */
    link?: string | null;
    /**
     * Optional. The banner hides itself after this time.
     */
    expiresAt?: string | null;
  };
  updatedAt?: string | null;
  createdAt?: string | null;
}
/**
 * Online payment also needs the Billplz keys in the server settings (see README). Without them, only pay-at-boutique is offered.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "shop-settings".
 */
export interface ShopSetting {
  id: number;
  /**
   * How long a piece stays held after a customer adds it to their cart. Maximum 24.
   */
  cartHoldHours: number;
  /**
   * How long a "reserve and pay at the boutique" order holds the piece before it returns to the shop.
   */
  payAtShopHoldHours: number;
  /**
   * If a cart hold is nearly over at checkout, it is extended by this much so the customer can finish paying.
   */
  paymentWindowMinutes: number;
  maxItemsPerCart: number;
  onlinePaymentEnabled?: boolean | null;
  payAtShopEnabled?: boolean | null;
  /**
   * Only offered with online payment. Collection at the boutique is always available.
   */
  deliveryEnabled?: boolean | null;
  deliveryFee?: number | null;
  /**
   * e.g. "Same-day delivery in the Klang Valley."
   */
  deliveryNote?: string | null;
  /**
   * Sold pieces stay in the shop marked "Sold" for this many days. 0 hides them straight away.
   */
  showSoldDays?: number | null;
  updatedAt?: string | null;
  createdAt?: string | null;
}
